function generate(rand, size) {
  const pick = rand();
  if (pick < 0.1) return [0];
  if (pick < 0.15) return [1000000];
  const top = size === 'large' ? 1000000 : 1000;
  let num = Math.floor(rand() * (top + 1));
  if (pick < 0.5) num = Math.floor(num / 10) * 10;
  if (pick < 0.6) num = Math.floor(num / 100) * 100;
  return [num];
}
